const fs = require("fs");
const crypto = require("crypto");
const { execSync } = require("child_process");

const files = [
  "crush.wasm",
  "hls-proxy.js",
  "http-client.js",
  "index.js",
  "package.json",
  "resolver.js",
  "services.json"
];

const ipkPath = "dist/com.cinejoy.tv_1.0.0_all.ipk";

console.log("Comparing SHA-256 of services/com.cinejoy.tv.service/ vs IPK payload:");

let allMatch = true;

for (const file of files) {
  const diskPath = "services/com.cinejoy.tv.service/" + file;
  const diskBuf = fs.readFileSync(diskPath);
  const diskSha = crypto.createHash("sha256").update(diskBuf).digest("hex");

  const ipkBuf = execSync(`ar -p "${ipkPath}" data.tar.gz | tar -zxf - "usr/palm/services/com.cinejoy.tv.service/${file}" -O`);
  const ipkSha = crypto.createHash("sha256").update(ipkBuf).digest("hex");

  const match = diskSha === ipkSha;
  if (!match) allMatch = false;

  console.log(`- ${file}:`);
  console.log(`    Disk: ${diskSha} (${diskBuf.length} bytes)`);
  console.log(`    IPK:  ${ipkSha} (${ipkBuf.length} bytes)`);
  console.log(`    Match: ${match ? "PASS (100% IDENTICAL)" : "FAIL (MISMATCH)"}`);
}

console.log("\nOverall services immutability verdict:", allMatch ? "ALL 7 FILES IDENTICAL" : "MUTATION DETECTED");
'

